                    const rem = len % 3;
                    const b64Len = (Math.floor(len / 3) * 4) + (rem ? 4 : 0);
                    const out = new Array(b64Len);
                    let o = 0;

                    // Process full 3-byte groups
                    const end = len - rem;
                    for (let i = 0; i < end; i += 3) {
                        const b0 = bytes[i], b1 = bytes[i + 1], b2 = bytes[i + 2];
                        out[o++] = CHARS[ b0 >> 2];
                        out[o++] = CHARS[(b0 & 0x03) << 4 | b1 >> 4];
                        out[o++] = CHARS[(b1 & 0x0f) << 2 | b2 >> 6];
                        out[o++] = CHARS[ b2 & 0x3f];
                    }

