            // features.sw = false unregisters it and drops its caches on the next load.
            window.LB_swSync = async function (f) {
                if (!('serviceWorker' in navigator) || (location.protocol !== 'http:' && location.protocol !== 'https:')) return;
                try {
                    if (f && f.sw === false) {
                        for (const r of await navigator.serviceWorker.getRegistrations()) {
                            const u = (r.active || r.waiting || r.installing || {}).scriptURL || '';
                            if (u.endsWith('/sw.js')) await r.unregister();
                        }
                        if (window.caches) for (const k of await caches.keys()) if (k.startsWith('lb-shell-')) await caches.delete(k);
                        return;
                    }
                    if (!window.LB_BUILD_SHA || window.LB_BUILD_SHA === 'dev') return;
                    await navigator.serviceWorker.register(new URL('sw.js', location.href).href, { scope: new URL('./', location.href).pathname });
                } catch (_) {}
            };
            window.LB_featuresReady.then((f) => {
                const go = () => setTimeout(() => window.LB_swSync(f), window.LB_SW_DELAY != null ? window.LB_SW_DELAY : 8000);
                if (document.readyState === 'complete') go(); else window.addEventListener('load', go, { once: true });
            });

            // ── Transport router (0.2.0) ────────────────────────────────────────
            // libcurl asks its transport for one WebSocket per TCP stream, with the url `<relay base><host>:<port>`.
            // LBTransport (set as libcurl.transport) passes that url through this router, which picks the relay:
            //   - our own relay (/wisp/): a shard /wisp/N/ (N in 1..ownSockets, least open streams first). libcurl keys its
            //     WISP connections on the base url, so each shard is its own WebSocket and the per-socket limits stop
            //     capping the whole browser. The gate accepts any /wisp/* path.
            //   - multi-relay (opt-in, needs third-party relays allowed): per-site sticky, spread, or race.
            // Everything here is a plain object built by LB_makeRouter(deps) so it can be tested with a stub Socket.
            function LB_makeRouter(d) {
                const sticky = new Map();      // hostname -> relay root (multi-relay)
                const sockets = new Map();     // final base url -> Set of live sockets
                const rootOf = new Map();      // final base url -> relay root it came from
                let shardCursor = 0, spreadCursor = 0;
                const R = {
                    pinned: null,              // set by LB_swapSession(url, {pin:true}) while a retry is on a chosen relay
                    sticky,
                    parse(raw) {
                        const i = raw.lastIndexOf('/');
                        const hp = raw.slice(i + 1);
                        const k = hp.lastIndexOf(':');
                        return { base: raw.slice(0, i + 1), hp, host: k < 0 ? hp : hp.slice(0, k), port: k < 0 ? '' : hp.slice(k + 1) };
                    },
                    multiActive() { return !!d.multiOn() && !R.pinned; },
                    ownCount() { const n = Math.floor(Number(d.ownSockets())); return Number.isFinite(n) ? Math.max(1, Math.min(4, n)) : 1; },
                    busy(base) {
                        const s = sockets.get(base);
                        if (!s) return 0;
                        for (const w of [...s]) { let rs; try { rs = w.readyState; } catch (_) { rs = 3; } if (rs === 3) s.delete(w); }
                        return s.size;
                    },
                    shard(root) {
                        const n = R.ownCount();
                        if (n <= 1) return root;
                        let best = null, bestBusy = Infinity;
                        for (let k = 0; k < n; k++) {
                            const cand = root + ((shardCursor + k) % n + 1) + '/';
                            const b = R.busy(cand);
                            if (b < bestBusy) { best = cand; bestBusy = b; }
                        }
                        shardCursor = (shardCursor + 1) % n;
                        return best;
                    },
                    finalBase(root) { return root && root === d.ownBase() ? R.shard(root) : root; },
                    route(raw) {
                        const p = R.parse(raw);
                        let roots = [p.base];
                        if (R.pinned) roots = [R.pinned];
                        else if (d.multiOn()) {
                            const mode = d.mode();
                            const ranked = d.candidates(p.host) || [];
                            if (ranked.length) {
                                const st = sticky.get(p.host);
                                if (mode === 'spread') roots = [ranked[spreadCursor++ % ranked.length]];
                                else if (st && (ranked.includes(st) || st === p.base)) roots = [st];
                                else if (mode === 'race' && p.port === '443' && ranked.length >= 2) roots = [ranked[0], ranked[1]];
                                else { roots = [ranked[0]]; sticky.set(p.host, ranked[0]); }
                            }
                        }
                        const bases = roots.map(R.finalBase);
                        bases.forEach((b, i) => rootOf.set(b, roots[i]));
                        const urls = bases.map(b => b + p.hp);
                        return { url: urls[0], base: bases[0], host: p.host, port: p.port, race: urls.length > 1 ? urls : null, bases };
                    },
                    track(base, ws) { let s = sockets.get(base); if (!s) sockets.set(base, s = new Set()); s.add(ws); },
                    untrack(base, ws) { const s = sockets.get(base); if (s) s.delete(ws); },
                    markFailed(base, host) {
                        const root = rootOf.get(base) || base;
                        if (sticky.get(host) === root) sticky.delete(host);
                        try { d.markFailed(root, host); } catch (_) {}
                    },
                    commit(base, host) { const root = rootOf.get(base) || base; if (d.multiOn()) sticky.set(host, root); },
                    make(url, base, host, p) {
                        const ws = new d.Socket(url, p);
                        R.track(base, ws);
                        let opened = false, failed = false;
                        const fail = () => { R.untrack(base, ws); if (!opened && !failed && !ws.__lbQuiet) { failed = true; R.markFailed(base, host); } };
                        ws.addEventListener('open', () => { opened = true; });
                        ws.addEventListener('error', fail);
                        ws.addEventListener('close', fail);
                        return ws;
                    },
                    open(raw, p) {
                        const r = R.route(raw);
                        if (r.race) return new LBRaceSocket(R, r, p);
                        return R.make(r.url, r.base, r.host, p);
                    },
                    reset() { sticky.clear(); }
                };
                return R;
            }

            // A socket that opens the same stream on two relays, sends to both until one of them answers, then keeps
            // only the winner (and remembers it for the host). Only used for port 443, where the first bytes are a
            // TLS ClientHello: nothing but the handshake is ever duplicated.
            class LBRaceSocket extends EventTarget {
                constructor(router, r, p) {
                    super();
                    this.CONNECTING = 0; this.OPEN = 1; this.CLOSING = 2; this.CLOSED = 3;
                    this.readyState = 0;
                    this._bt = 'blob';
                    this.onopen = () => {}; this.onerror = () => {}; this.onmessage = () => {}; this.onclose = () => {};
                    this._router = router; this._host = r.host; this._sent = []; this._winner = null; this._opened = false; this._closed = false;
                    this._inner = r.race.map((url, i) => {
                        const rec = { ws: null, base: r.bases[i], open: false, dead: false };
                        const ws = router.make(url, rec.base, r.host, p);
                        rec.ws = ws;
                        try { ws.binaryType = this._bt; } catch (_) {}
                        ws.addEventListener('open', () => this._onInnerOpen(rec));
                        ws.addEventListener('message', (e) => this._onInnerMessage(rec, e));
                        const gone = () => this._onInnerGone(rec);
                        ws.addEventListener('error', gone);
                        ws.addEventListener('close', gone);
                        return rec;
                    });
                }
                get binaryType() { return this._bt; }
                set binaryType(v) { this._bt = v; for (const r of this._inner) { try { r.ws.binaryType = v; } catch (_) {} } }
                get protocol() { return 'binary'; }
                get extensions() { return ''; }
                get bufferedAmount() { let n = 0; for (const r of this._inner) { if (!r.dead) { try { n += r.ws.bufferedAmount || 0; } catch (_) {} } } return n; }
                _fire(type, ev) { const h = this['on' + type]; try { h && h.call(this, ev); } catch (e) { console.error(e); } this.dispatchEvent(ev); }
                _onInnerOpen(rec) {
                    if (this._closed || rec.dead) return;
                    rec.open = true;
                    if (!this._winner) for (const c of this._sent) { try { rec.ws.send(c); } catch (_) {} }
                    if (!this._opened) { this._opened = true; this.readyState = 1; this._fire('open', new Event('open')); }
                }
                _onInnerMessage(rec, e) {
                    if (this._closed || rec.dead) return;
                    if (!this._winner) {
                        this._winner = rec;
                        this._sent = [];
                        for (const o of this._inner) if (o !== rec) { o.dead = true; o.ws.__lbQuiet = true; try { o.ws.close(); } catch (_) {} }
                        this._router.commit(rec.base, this._host);
                    }
                    if (this._winner !== rec) return;
                    this._fire('message', new MessageEvent('message', { data: e.data }));
                }
                _onInnerGone(rec) {
                    if (rec.dead) return;
                    rec.dead = true;
                    if (this._closed) return;
                    if (this._winner === rec || !this._inner.some(o => !o.dead)) {
                        const wasOpen = this._opened;
                        this._closed = true; this.readyState = 3;
                        if (!wasOpen) this._fire('error', new Event('error'));
                        this._fire('close', new CloseEvent('close', { code: 1006 }));
                    }
                }
                send(data) {
                    if (this._closed) throw 'websocket is not ready';
                    if (!this._winner) {
                        let copy = data;
                        try { copy = data instanceof ArrayBuffer ? data.slice(0) : ArrayBuffer.isView(data) ? new Uint8Array(data.buffer.slice(data.byteOffset, data.byteOffset + data.byteLength)) : data; } catch (_) {}
                        this._sent.push(copy);
                        for (const r of this._inner) if (r.open && !r.dead) { try { r.ws.send(data); } catch (_) {} }
                    } else {
                        this._winner.ws.send(data);
                    }
                }
                close() {
                    if (this._closed) return;
                    this._closed = true; this.readyState = 3;
                    for (const r of this._inner) { r.dead = true; r.ws.__lbQuiet = true; try { r.ws.close(); } catch (_) {} }
                    this._fire('close', new CloseEvent('close', { code: 1000 }));
                }
            }

            const LB_OWN_SOCKETS_KEY = 'limitless:ownsockets:v1';
            const LB_MULTI_KEY = 'limitless:multirelay:v1';
            const LB_MULTI_MODE_KEY = 'limitless:multirelay-mode:v1';
            function lbOwnSocketsSetting() { try { const n = parseInt(ls.getItem(LB_OWN_SOCKETS_KEY), 10); return n >= 1 && n <= 4 ? n : 4; } catch { return 4; } }
            function lbMultiMode() { try { const m = ls.getItem(LB_MULTI_MODE_KEY); return m === 'spread' || m === 'race' ? m : 'site'; } catch { return 'site'; } }
            const LB_router = LB_makeRouter({
                ownBase: () => LB_OUR_WISP,
                ownSockets: () => (LB_OUR_WISP ? Math.min(lbOwnSocketsSetting(), window.LB_features.ownSockets) : 1),
                // Multi-relay needs third-party relays to be allowed; the switch is locked in Settings otherwise.
                multiOn: () => { try { return LB_fallbackAllowed && ls.getItem(LB_MULTI_KEY) === '1'; } catch { return false; } },
                mode: lbMultiMode,
                candidates: (host) => rankPoolCandidates(host, null),
                markFailed: markWispFailed,
                get Socket() { return libcurl.wisp.WispWebSocket; },
            });
            window.LB_makeRouter = LB_makeRouter;
            window.LB_router = LB_router;
            class LBTransport {
                constructor(url, protocols) { return LB_router.open(url, protocols); }
            }
            libcurl.transport = LBTransport;

            // One place that swaps the libcurl session: points libcurl at `url`, creates the new session, applies the
            // connection limits, and closes the old one once it has no requests in flight (the old code leaked every one).
            async function LB_swapSession(url, opts) {
                await libcurl.load_wasm();
                libcurl.set_websocket(url);
                LB_router.pinned = opts && opts.pin ? url : null;
                const old = curl;
                const next = new libcurl.HTTPSession();
                lbApplyConnections(next);
                curl = next;
                if (old && old !== next) {
                    const t0 = Date.now();
                    (function retire() {
                        let idle = true;
                        try { idle = !old.active_requests; } catch (_) {}
                        if (idle || Date.now() - t0 > 60000) { try { old.close(); } catch (_) {} return; }
                        setTimeout(retire, 500);
                    })();
                }
                return next;
            }
            window.LB_swapSession = LB_swapSession;
            window.LB_net = { get curl() { return curl; }, set curl(v) { curl = v; } };   // test hook

            // Settings > Connection: sockets to our relay, multi-relay switch and mode.
            (function () {
                const val = document.getElementById('settingsSocketsVal');
                const minus = document.getElementById('settingsSocketsMinus'), plus = document.getElementById('settingsSocketsPlus');
                const render = () => {
                    const n = lbOwnSocketsSetting();
                    if (val) val.textContent = String(n);
                    if (minus) minus.disabled = n <= 1;
                    if (plus) plus.disabled = n >= 4;
                };
                const set = (n) => { try { ls.setItem(LB_OWN_SOCKETS_KEY, String(Math.max(1, Math.min(4, n)))); } catch (_) {} render(); };
                if (minus) minus.addEventListener('click', () => set(lbOwnSocketsSetting() - 1));
                if (plus) plus.addEventListener('click', () => set(lbOwnSocketsSetting() + 1));
                render();

                const sw = document.getElementById('settingsMultiRelaySwitch');
                const mode = document.getElementById('settingsMultiRelayMode');
                const note = document.getElementById('settingsMultiRelayNote');
                if (!sw || !mode) return;
                const locked = !LB_fallbackAllowed;
                const on = () => { try { return ls.getItem(LB_MULTI_KEY) === '1'; } catch { return false; } };
                const paint = () => {
                    sw.classList.toggle('disabled', locked);
                    sw.setAttribute('aria-disabled', locked ? 'true' : 'false');
                    sw.classList.toggle('on', !locked && on());
                    mode.disabled = locked;
                    mode.value = lbMultiMode();
                };
                const lockedNote = 'Locked. Turn on "Allow third-party relays" above first; this feature spreads your connections over those relays. ';
                const unlockedNote = 'These relays are run by other operators, not by Gamble Limited Ltd. A relay can see which sites you visit, though not what is inside secure (https) connections. ' +
                    'Per site keeps each site on one relay. Spread sends each connection through a different relay, which can sign you out of sites or trigger bot checks. ' +
                    'Race starts a secure connection on two relays at once and keeps the faster one, so the first bytes go to both.';
                if (note) note.textContent = (locked ? lockedNote : '') + unlockedNote;
                sw.addEventListener('click', () => {
                    if (locked) return;
                    try { ls.setItem(LB_MULTI_KEY, on() ? '0' : '1'); } catch (_) {}
                    LB_router.reset();
                    paint();
                });
                mode.addEventListener('change', () => {
                    if (locked) return;
                    try { ls.setItem(LB_MULTI_MODE_KEY, mode.value); } catch (_) {}
                    LB_router.reset();
                });
                paint();
            })();

            const $ = s => document.getElementById(s);
            const frame = $('frame');
            // Self-hosted assets. Documents we generate (blob:/srcdoc:) need absolute URLs.
            const LB_ASSET = p => { try { return new URL(p, document.baseURI).href; } catch (e) { return p; } };
            const LB_FA = LB_ASSET('vendor/fontawesome/6.7.2/css/all.min.css');
            const LB_FONTS_CSS = LB_ASSET('fonts/fonts.css');
            const LB_PDFJS = LB_ASSET('vendor/pdfjs/4.2.67/');
            let _pendingNavHint = null;
            // Set to true right before we assign a blob URL to frame.src.
            // Cleared at the start of the load event so we can distinguish
            // our own intentional blob loads from native iframe escapes.
            // (Chrome treats blob URLs from file:// pages as cross-origin,
            //  so .location.href throws for both cases in the catch below.)
            let _blobLoadPending = false;

            // ── Native navigation escape interceptor ──────────────────────
            // If a proxied page causes the iframe to navigate natively
            // (e.g. Brave search redirect links that bypass the postMessage
            // click intercept), catch the load event, read the landed URL,
            // and re-route it through the proxy immediately.
            frame.addEventListener('load', () => {
                const _wasBlobLoad = _blobLoadPending;
                _blobLoadPending = false;
                try {
                    const landed = frame.contentWindow?.location?.href;
                    if (!landed || landed === 'about:blank' || landed === 'about:srcdoc' || landed.startsWith('blob:')) return;
                    // iframe landed on a real URL natively — reroute via proxy
                    _pendingNavHint = null;
                    frame.src = 'about:blank';
                    go(landed, true);
                } catch (crossOriginErr) {
                    // .location.href throws for cross-origin pages AND for blob URLs
                    // loaded from a file:// context (Chrome treats them as null-origin).
                    // Use _wasBlobLoad to tell them apart: if we just intentionally
                    // loaded a blob, this is not a native escape — bail out.
                    if (_wasBlobLoad) return;
                    // Real native escape to a cross-origin URL — recover.
                    try {
                        const hint = _pendingNavHint;
                        _pendingNavHint = null;
                        const escapedSrc = frame.src;
                        const recoveryUrl = (hint && !hint.startsWith('blob:') && hint !== 'about:blank')
                            ? hint
                            : (escapedSrc && !escapedSrc.startsWith('blob:') && escapedSrc !== 'about:blank')
                                ? escapedSrc
                                : null;
                        if (recoveryUrl) {
                            frame.src = 'about:blank';
                            go(recoveryUrl, true);
                        } else {
                            // No real escape — the page triggered a NATIVE reload() of the
                            // blob doc (e.g. Next.js hydration / chunk-error recovery).
                            // Reload the current proxied URL instead of blanking.
                            // Guard against self-looping: only reload if a page actually
                            // loaded successfully before (_lastPageLoadTime is set on the
                            // 'ready' message), and self-throttle by stamping the time so a
                            // reload that itself fails can't re-fire for 15s. Never reload
                            // when nothing ever loaded (_lastPageLoadTime === 0) — that path
                            // is the dead-server / in-flight case and would loop forever.
                            if (pageUrl && _lastPageLoadTime && (Date.now() - _lastPageLoadTime) > 15000) {
                                _lastPageLoadTime = Date.now();
                                go(pageUrl, false);
                            }
                        }
                    } catch (_) {}
                }
            }, true);
