            function bindElementViewerInteractions() {
                if (!elementsTree) return;
                elementsTree.addEventListener('click', function(e) {
                    let target = e.target;
                    while (target && !target.classList.contains('element-content')) {
                        target = target.parentElement;
                    }
                    if (target && target.dataset && target.dataset.selector) {
                        highlightElementInPage(target.dataset.selector);
                        elementsTree.querySelectorAll('.element-content.selected').forEach(el => el.classList.remove('selected'));
                        target.classList.add('selected');
                    }
                });
            }

            bindElementViewerInteractions();

            let curl = null;
            let abortCtrl = null;
            let pageUrl = "";
            let isErrorPage = false; 
            let currentDoc = null; 
            let hist = [];
            let histIdx = -1;
            let navId = 0; 
            let selectedEngine = (function () { try { return ls.getItem('limitless:engine:v1') || 'ddg'; } catch { return 'ddg'; } })();

            let totalRequests = 0;
            let pendingRequests = 0;
            let cachedHits = 0;
            let streamCount = 0;
