                        const _rootEl = document.getElementById('newtab');
                        if (!_rootEl) return;
                        let _mutationCount = 0;
                        new MutationObserver(()=>{
                        }).observe(_rootEl,{attributes:true,childList:true,subtree:true,characterData:true});
