            let wallpaperGradientIdx = 0;

            // Apply a wallpaper, routing any remote URL through the proxy (WISP)
            // instead of fetching it directly from the top-level Limitless page.
            // data:/blob: URLs are applied as-is. `store` persists the source URL
            // so it survives reloads (blob URLs don't, so we re-proxy on load).
            async function applyBgFromUrl(url, store) {
                if (!ntBg || !url) return;
                if (/^(data:|blob:)/i.test(url)) {
                    ntBg.style.backgroundImage = `url(${url})`;
                    ntBg.style.backgroundSize = "cover";
                    ntBg.style.backgroundPosition = "center";
                    if (store) { try { ls.setItem(WALLPAPER_STORAGE_KEY, url); } catch (_) { } }
                    return;
                }
                try {
                    const r = await queueFetch(url, {}, PRIORITY.image);
                    if (!r.buf || !r.buf.byteLength) return;
                    const blobUrl = URL.createObjectURL(new Blob([r.buf], { type: r.mime || 'image/jpeg' }));
                    ntBg.style.backgroundImage = `url(${blobUrl})`;
                    ntBg.style.backgroundSize = "cover";
                    ntBg.style.backgroundPosition = "center";
                    if (store) { try { ls.setItem(WALLPAPER_STORAGE_KEY, url); } catch (_) { } }
                } catch (_) { /* leave the gradient fallback showing */ }
            }

            function applyWallpaperUrl(url) {
                if (!ntBg || !url) return;
                applyBgFromUrl(url, true);
            }

            function loadSavedWallpaper() {
                if (!ntBg) return;
                ntBg.style.backgroundSize = "cover";
                ntBg.style.backgroundPosition = "center";
                ntBg.style.backgroundImage = WALLPAPER_GRADIENTS[0];
                try {
                    const saved = ls.getItem(WALLPAPER_STORAGE_KEY);
                    if (saved && (saved.startsWith("http") || saved.startsWith("data:"))) {
                        applyBgFromUrl(saved, false);
                    }
                } catch (_) { }
            }

            function loadFavorites() {
                try {
                    const raw = ls.getItem(FAV_KEY);
                    favorites = raw ? JSON.parse(raw) : [];
                } catch { favorites = []; }}

            function saveFavorites() {
                try { ls.setItem(FAV_KEY, JSON.stringify(favorites)); } catch (_) { }
            }


            function renderFavorites() {
                if (!ntFavorites) return;
                ntFavorites.innerHTML = "";

                for (const fav of favorites) {
                    if (!fav || !fav.url || fav.url === HOME_INTERNAL) continue;
                    try {
                        let name = (fav.name && fav.name.trim()) ? fav.name : "";
                        if (!name) try { name = new URL(fav.url).hostname.replace(/^www\./, ""); } catch (_) { name = fav.url; }

                        const wrapper = document.createElement("div");
                        wrapper.className = "nt-fav-wrapper";

                        const a = document.createElement("a");
                        a.className = "nt-fav-box";
                        a.href = "#";
                        a.title = fav.url;
                        a.innerHTML = `
                            <img alt="" data-favicon-url="${faviconFor(fav.url)}">
                            <button class="nt-fav-delete" title="Remove favorite">
                                <i class="fas fa-trash"></i>
                            </button>
                        `;

                        const favImg = a.querySelector('img[data-favicon-url]');
                        if (favImg) {
                            // Initial letter shows until the icon has really loaded (also covers offline and failed icons).
                            const initial = document.createElement('span');
                            initial.className = 'nt-fav-initial';
                            initial.setAttribute('aria-hidden', 'true');
                            initial.textContent = (name.trim()[0] || '?').toUpperCase();
                            favImg.style.display = 'none';
                            a.insertBefore(initial, favImg);
                            favImg.addEventListener('load', () => { initial.remove(); favImg.style.display = ''; });
                            favImg.addEventListener('error', () => { favImg.style.display = 'none'; });
                            resolveFaviconSrc(favImg.getAttribute('data-favicon-url')).then(src => { if (src) favImg.src = src; }).catch(() => {});
                        }

                        const titleSpan = document.createElement("span");
                        titleSpan.className = "nt-fav-title";
                        titleSpan.textContent = name;

                        a.addEventListener("click", (e) => {
                            if (e.target.closest('.nt-fav-delete')) {
                                e.preventDefault();
                                e.stopPropagation();
                                return;
                            }
                            e.preventDefault();
                            go(fav.url, true);
                        });

                        const deleteBtn = a.querySelector('.nt-fav-delete');
                        deleteBtn.addEventListener('click', (e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            favorites = favorites.filter(f => f.url !== fav.url);
                            saveFavorites();
                            renderFavorites();
                        });

                        wrapper.appendChild(a);
                        wrapper.appendChild(titleSpan);
                        ntFavorites.appendChild(wrapper);
                    } catch (_) { }
                }

                if (favorites.length < 6) {
                const addWrapper = document.createElement("div");
                addWrapper.className = "nt-fav-wrapper";

                const addBtn = document.createElement("button");
                addBtn.className = "nt-fav-add";
                addBtn.id = "ntFavAddBtn";
                addBtn.type = "button";
                addBtn.title = "Add a shortcut";

                if (favorites.length >= 6) {
                    addBtn.classList.add("disabled");
                    addBtn.title = "Maximum 6 shortcuts";
                    addBtn.disabled = true;
                }

                addBtn.innerHTML = "<i class=\"fas fa-plus\"></i>";
                addBtn.addEventListener("click", (e) => {
                    e.preventDefault();
                    if (favorites.length < 6) {
                        showAddFavoriteModal();
                    }
                });

                const addLabel = document.createElement("span");
                addLabel.className = "nt-fav-title";
                addLabel.textContent = "Add";

                addWrapper.appendChild(addBtn);
                addWrapper.appendChild(addLabel);
                ntFavorites.appendChild(addWrapper);
                }
            }

            let _lbAnimLocked = false;
