                    '.kw{color:#9de5ff}.str{color:#8aefb0}.num{color:#f8dc75}.lit{color:#ff9595}.cmt{color:#3a4250;font-style:italic}',
                    '#wordwrapBtn.active{background:rgba(157,229,255,.12);border-color:rgba(157,229,255,.4);color:#9de5ff}',
