            let _anyResizing = false; 

            function setupPanelResize(panel, handle) {
                if (!panel || !handle) return;

                let isResizing = false;
                let startX = 0;
                let startWidth = 0;

                handle.addEventListener('mousedown', (e) => {
                    isResizing = true;
                    _anyResizing = true;
                    startX = e.clientX;
                    startWidth = panel.offsetWidth;
                    document.body.style.cursor = 'ew-resize';
                    if (frame) frame.style.pointerEvents = 'none';
                    e.preventDefault();
                });

                document.addEventListener('mousemove', (e) => {
                    if (!isResizing) return;
                    const panelsLeft = document.body.classList.contains('panels-left');
                    const deltaX = panelsLeft ? e.clientX - startX : startX - e.clientX;
                    const newWidth = Math.max(250, Math.min(800, startWidth + deltaX));
                    panel.style.width = newWidth + 'px';
                    if (window._updateFindBarPos) window._updateFindBarPos();
                });

                const stopResize = () => {
                    if (isResizing) {
                        isResizing = false;
                        _anyResizing = false;
                        document.body.style.cursor = '';
                        if (frame) frame.style.pointerEvents = '';
                    }
                };

                document.addEventListener('mouseup', stopResize);
                window.addEventListener('blur', stopResize);
                document.addEventListener('mouseleave', stopResize);
            }

            setupPanelResize(logsEl, logsResizeHandle);
            setupPanelResize(elementsEl, elementsResizeHandle);

            
            const SC_ACTIONS = {
                newtab: () => createTab(),
                closetab: () => { if (tabs.length > 1) closeTabAnimated(activeTabId); },
                reload: () => { if (pageUrl && pageUrl !== HOME_INTERNAL) go(pageUrl, false); },
                bookmark: () => { if (pageUrl && pageUrl !== HOME_INTERNAL) showBookmarkModal(); },
                focusurl: () => { urlInput.focus(); urlInput.select(); },
                settings: () => showSettingsPage(true),
                logs: () => { if (logsEl) logsEl.classList.toggle('hidden'); },
                inspector: () => { toggleElements(); },
                history: () => { if (historyPopup.classList.contains('open')) hideHistoryPopup(); else showHistoryPopup(); },
                metrics: () => { metricsModal.style.display === 'flex' ? hideMetrics() : showMetrics(); },
                fullscreen: () => { if (!document.fullscreenElement) _doRequestFullscreen().catch(() => {}); else document.exitFullscreen(); },
                find: () => toggleFindBar()
            };
            const SC_DEFAULTS = { newtab: 'T', closetab: 'W', reload: 'R', bookmark: 'D', focusurl: 'L', settings: ',', logs: 'G', inspector: 'I', history: 'H', metrics: 'M', fullscreen: 'K', find: 'F' };
            let scMap = {}; 

            function buildShortcutMap() {
                scMap = {};
                for (const [name, def] of Object.entries(SC_DEFAULTS)) {
                    let key = def;
                    try { key = ls.getItem('limitless:sc:' + name) || def; } catch (e) { }
                    scMap[key.toUpperCase()] = name;
                }
            }
            buildShortcutMap();

            document.addEventListener("keydown", (e) => {
                const modal = $("shortcutEditModal");
                if (modal && modal.style.display === 'flex') return;
                let scEnabled = true;
                try { if (ls.getItem('limitless:shortcutsEnabled') === '0') scEnabled = false; } catch(e) {}
                if (!scEnabled) return;

                if (e.altKey && e.key !== 'Alt') {
                    const k = e.key === ',' ? ',' : e.key.toUpperCase();
                    const action = scMap[k] || scMap[e.key.toUpperCase()];
                    if (action && SC_ACTIONS[action]) {
                        const tag = document.activeElement?.tagName;
                        if (tag === 'INPUT' || tag === 'TEXTAREA') {
                            if (action !== 'find') return;
                        }
                        e.preventDefault();
                        SC_ACTIONS[action]();
                    }
                }
            });


