                // Skins hardcode their palettes, so a theme shows under default Limitless
                // and the Limitless parts of Limitless+ — same ceiling the Color Lab has.
                const themeRegistry = new Map(); // active theme only: id -> display meta
                const isThemeManifest = m => !!(m && m.theme);
