                    const toolbarFg = _guard(col('bookmark_text') || col('tab_text'), toolbar);
                    const omniBg = col('omnibox_background') || (toolbar ? _shade(toolbar, _lum(toolbar) > 0.4 ? -20 : 24) : null);
                    const omniFg = _guard(col('omnibox_text'), omniBg);
