                        // the anchor button is re-created whenever renderIcons() runs
                        // (badge updates) — re-resolve it or its rect collapses to 0,0
                        let el = (anchor && anchor.isConnected) ? anchor : extBar.querySelector('[data-ext="' + id + '"]');
